# Bound one channel write that returns without waiting for playback. A stuck
# socket must not hold the stream. A send that exceeds this is cancelled and
# not stored, so the terminal reply still contains the text.
_INTERMEDIATE_SEND_TIMEOUT_SECONDS = 10.0

# Voice waits for earlier audio and then streams TTS. Two minutes covers a
# long reply. Past this the stream moves on and the write is left running, so
# playback is not cut off and a hung provider cannot hold the turn forever.
_PLAYBACK_SEND_TIMEOUT_SECONDS = 120.0


def _intermediate_send_timeout(output_channel: OutputChannel) -> tuple[float, bool]:
    """Return ``(seconds, cancel_on_timeout)`` for one channel write.

    Playback gets the longer bound and is not cancelled when it expires.
    Cancelling it would cut off audio, and the terminal reply would say the
    utterance again because the send was not stored. Other writes are
    cancelled so a stuck socket does not stay open.
    """
    if output_channel.send_text_message_awaits_playback():
        return _PLAYBACK_SEND_TIMEOUT_SECONDS, False
    return _INTERMEDIATE_SEND_TIMEOUT_SECONDS, True


def _consume_send_result(task: asyncio.Task[None]) -> None:
    """Retrieve a background send's exception so it is not reported later."""
    if task.cancelled():
        return
    task.exception()


def _channel_send_succeeded(task: asyncio.Task[None]) -> bool:
    """True when the channel write has returned without error."""
    if not task.done() or task.cancelled():
        return False
    return task.exception() is None


def _task_state_name(state: int) -> str:
    """Return the proto enum name, such as ``TASK_STATE_FAILED``."""
    try:
        return TaskState.Name(state)
    except ValueError:
        return str(state)


def _jsonrpc_interface_url(card: AgentCard) -> str:
    """URL of the JSON-RPC interface on a 1.0 card.

    A 0.3 card's ``url`` is already copied onto ``supported_interfaces`` by
    ``parse_agent_card`` before this helper runs.
    """
    if not isinstance(card, AgentCard):
        return ""
    fallback = ""
    for interface in card.supported_interfaces:
        if interface.protocol_binding == TransportProtocol.JSONRPC:
            return interface.url
        if not fallback and interface.url:
            fallback = interface.url
    return fallback


def _apply_stream_chunk(
    chunk: StreamResponse, current: Optional[Task]
) -> tuple[Optional[Task], Optional[Message]]:
    """Fold one stream chunk into the task accumulated so far.

    Returns ``(task, message)``. A ``message`` chunk is returned as the
    second element and does not replace the task.
    """
    if chunk.HasField("message"):
        return current, chunk.message
    if chunk.HasField("task"):
        return chunk.task, None
    if chunk.HasField("status_update"):
        return _task_with_status(current, chunk.status_update), None
    if chunk.HasField("artifact_update"):
        return _task_with_artifact(current, chunk.artifact_update), None
    return None, None


def _task_with_status(current: Optional[Task], update: TaskStatusUpdateEvent) -> Task:
    task = Task()
    if current is not None:
        task.CopyFrom(current)
    if update.task_id:
        task.id = update.task_id
    if update.context_id:
        task.context_id = update.context_id
    if update.HasField("status"):
        task.status.CopyFrom(update.status)
    return task


def _task_with_artifact(
    current: Optional[Task], update: TaskArtifactUpdateEvent
) -> Task:
    """Fold an artifact update into the task, matching artifacts by id.

    Mirrors the SDK's ``append_artifact_to_task``: ``append`` extends the
    parts of the stored artifact with the same ``artifact_id`` wherever it
    sits in ``task.artifacts``; without ``append`` an artifact with the same
    id is replaced. An unknown id is added as a new artifact either way.
    """
    task = Task()
    if current is not None:
        task.CopyFrom(current)
    if update.task_id:
        task.id = update.task_id
    if update.context_id:
        task.context_id = update.context_id
    if not update.HasField("artifact"):
        return task
    artifact = update.artifact
    existing = next(
        (
            stored
            for stored in task.artifacts
            if stored.artifact_id == artifact.artifact_id
        ),
        None,
    )
    if existing is None:
        task.artifacts.append(artifact)
    elif update.append:
        existing.parts.extend(artifact.parts)
        existing.metadata.update(dict(artifact.metadata.items()))
    else:
        existing.CopyFrom(artifact)
    return task


class StreamResult(NamedTuple):
    """Result of consuming an A2A streaming response."""

    agent_output: Optional[AgentOutput]
    task_id: Optional[str]
    events_received: int


class _IntermediateSendOutcome(enum.Enum):
    """How a wait for one intermediate channel write ended."""

    SENT = "sent"
    TIMED_OUT = "timed_out"


class _SentIntermediateRecords:
    """What one agent run has already shown the user, and how.

    Mutable so the stream and a later poll share it. Statuses that carry a
    ``message_id`` are deduped by that id when the send is scheduled, so a
    later poll of the same status is not sent again. Statuses without an id
    are always sent while streaming and deduped by text while polling.

    The texts used to trim the terminal reply are recorded only when the send
    succeeds and its ``BotUttered`` is appended. A failed send is therefore
    still part of the terminal reply. Each shown segment removes one matching
    terminal segment, from the end of the reply, so a later successful ``OK``
    does not also drop an earlier ``OK`` that never reached the user. That is
    preferred to dropping text the user never saw, even though it can reorder
    the channel: if an earlier status fails and a later one succeeds, the user
    may already have seen the later text live, then get the failed earlier text
    again in the terminal reply. We accept that rare case rather than
    re-uttering the full terminal text (which would duplicate the successful
    intermediate) or merging the failed text into the next live send.

    It also keeps the ids of token artifacts that a status message in the run
    linked to, and the utterance text of that link. The stream replaces
    ``status.message`` on every status update, so a link seen on an earlier
    status is only known from here. A linked artifact's text is left out of
    the terminal reply when that utterance was appended as a ``BotUttered``,
    or when the terminal status still contains it. Otherwise the artifact
    text stays, so a failed live send is not dropped.

    Each intermediate send is awaited before the next stream or poll event is
    handled. A channel that does not wait for playback is bounded by a short
    timeout and cancelled when it expires. Voice playback gets a longer bound
    and is left running if that expires, so the audio is not cut off. The
    ``BotUttered`` is stored only when that send finishes in time. A timed-out
    send is left unshown so the stream continues.
    Cancelling the turn does not wait for an in-flight write. If the channel
    already delivered that text, the tracker has no ``BotUttered`` for it.
    """

    def __init__(self) -> None:
        self._message_ids: set[str] = set()
        self._texts_without_id: set[str] = set()
        self._shown_texts: list[str] = []
        self._shown_artifact_ids: set[str] = set()
        self._streamed_artifact_ids: set[str] = set()
        self._artifact_link_texts: dict[str, str] = {}

    @property
    def shown_texts(self) -> list[str]:
        """Texts stored as intermediate ``BotUttered`` events, in order."""
        return list(self._shown_texts)

    @property
    def shown_artifact_ids(self) -> frozenset[str]:
        """Ids whose linking utterance was appended as a ``BotUttered``."""
        return frozenset(self._shown_artifact_ids)

    @property
    def streamed_artifact_ids(self) -> frozenset[str]:
        """Ids of token artifacts linked by a message seen in the run."""
        return frozenset(self._streamed_artifact_ids)

    @property
    def artifact_link_texts(self) -> dict[str, str]:
        """Utterance text of each linked artifact seen in the run."""
        return dict(self._artifact_link_texts)

    def record_streamed_artifacts(self, task: Task) -> None:
        """Remember the token artifacts linked by the task's messages."""
        self._streamed_artifact_ids.update(_streamed_artifact_ids(task))
        self._artifact_link_texts.update(_artifact_link_texts(task))

    def should_skip(self, message_id: str, text: str, *, dedupe_text: bool) -> bool:
        """Test whether this status was already scheduled in the run."""
        if message_id:
            return message_id in self._message_ids
        return dedupe_text and text in self._texts_without_id

    def record(self, message_id: str, text: str) -> None:
        """Remember a scheduled send so a duplicate status is not sent again.

        This does not mark the text as shown. ``record_shown`` does that, and
        only after the tracker event is stored.
        """
        if message_id:
            self._message_ids.add(message_id)
            return
        self._texts_without_id.add(text)

    def record_shown(self, text: str, *, artifact_id: str = "") -> None:
        """Remember text that was stored as an intermediate ``BotUttered``."""
        self._shown_texts.append(text)
        if artifact_id:
            self._shown_artifact_ids.add(artifact_id)


def _task_messages(task: Task) -> list[Message]:
    """Status message plus history. GetTask returns earlier statuses there."""
    messages = list(task.history)
    if task.status.HasField("message"):
        messages.append(task.status.message)
    return messages


def _streamed_artifact_id(message: Message) -> str:
    """Artifact id linked by the message, or an empty string."""
    value = message.metadata.fields.get(STREAMED_ARTIFACT_ID_METADATA_KEY)
    if value is None:
        return ""
    return value.string_value


def _streamed_artifact_ids(task: Task) -> set[str]:
    """Ids of token artifacts named by ``streamed_artifact_id`` in the task."""
    return {
        artifact_id
        for message in _task_messages(task)
        if (artifact_id := _streamed_artifact_id(message))
    }


def _artifact_link_texts(task: Task) -> dict[str, str]:
    """Utterance text of each message that links a token artifact."""
    texts: dict[str, str] = {}
    for message in _task_messages(task):
        artifact_id = _streamed_artifact_id(message)
        if not artifact_id:
            continue
        text = A2AAgent._generate_response_message_from_parts(message.parts)
        if text:
            texts[artifact_id] = text
    return texts


def _skip_linked_artifact_text(
    artifact_id: str,
    *,
    status_message: str,
    shown_artifact_ids: AbstractSet[str],
    link_texts: Mapping[str, str],
) -> bool:
    """Whether a linked artifact's text is already covered elsewhere.

    Skip it when the linking utterance was appended as a ``BotUttered``, or
    when that utterance is still on the terminal status. Otherwise the text
    parts stay, so a failed send can be recovered from the artifact.
    """
    if artifact_id in shown_artifact_ids:
        return True
    link_segments = _split_utterance_segments(link_texts.get(artifact_id, ""))
    if not link_segments:
        return False
    status_segments = set(_split_utterance_segments(status_message))
    return all(segment in status_segments for segment in link_segments)


def _split_utterance_segments(text: str) -> list[str]:
    return [
        segment.strip()
        for segment in text.split(TERMINAL_TEXT_SEPARATOR)
        if segment.strip()
    ]


def _remove_sent_utterances(terminal_text: str, shown_texts: List[str]) -> str:
    """Drop one terminal segment per segment that was already shown.

    Rasa joins the utterances of a turn with a blank line. Each shown segment
    removes one matching terminal segment, starting from the end, so an earlier
    unsent copy of the same text stays. The original string is returned when
    none of its segments were shown.

    Args:
        terminal_text: The text of the input-required or completed status.
        shown_texts: Texts stored as intermediate messages.

    Returns:
        The terminal text with one segment removed per shown segment. Empty
        when every segment was already shown.
    """
    shown_counts: Counter[str] = Counter(
        segment for text in shown_texts for segment in _split_utterance_segments(text)
    )
    segments = _split_utterance_segments(terminal_text)
    remaining: list[str] = []
    for segment in reversed(segments):
        if shown_counts[segment] > 0:
            shown_counts[segment] -= 1
            continue
        remaining.append(segment)
    remaining.reverse()
    if remaining == segments:
        return terminal_text
    return TERMINAL_TEXT_SEPARATOR.join(remaining)


class A2AAgent(AgentProtocol):
    """A2A client implementation."""

    __SUPPORTED_OUTPUT_MODES: ClassVar[list[str]] = [
        "text",
        "text/plain",
        "application/json",
    ]

    # ============================================================================
    # Initialization & Setup
    # ============================================================================

    def __init__(
        self,
        name: str,
        description: str,
        agent_card_path: str,
        timeout: int,
        max_retries: int,
        max_polling_time: int = A2A_TASK_POLLING_MAX_WAIT,
        polling_initial_delay: float = A2A_TASK_POLLING_INITIAL_DELAY,
        auth_config: Optional[Dict[str, Any]] = None,
        push_notification_url: Optional[str] = None,
        pre_call_hook: Optional[str] = None,
    ) -> None:
        self._name = name
        self._description = description
        self._agent_card_path = agent_card_path
        self._timeout = timeout
        self._max_retries = max_retries
        self._auth_config = auth_config
        self._max_polling_time = max_polling_time
        self._polling_initial_delay = polling_initial_delay
        self._push_notification_url = push_notification_url
        self._pre_call_hook = pre_call_hook

        self._push_notification_url = (
            self._push_notification_url.removesuffix("/")
            if self._push_notification_url
            else None
        )

        self.agent_card: Optional[AgentCard] = None
        self._client: Optional[Client] = None

    @classmethod
    def from_config(cls, config: AgentConfig) -> AgentProtocol:
        """Initialize the A2A Agent with the given configuration."""
        agent_card_path = (
            config.configuration.agent_card if config.configuration else None
        )
        if not agent_card_path:
            raise InvalidParameterException(
                "Agent card path or URL must be provided in the configuration "
                "for A2A agents."
            )

        timeout = (
            config.configuration.timeout
            if config.configuration and config.configuration.timeout
            else AGENT_DEFAULT_TIMEOUT_SECONDS
        )
        max_retries = (
            config.configuration.max_retries
            if config.configuration and config.configuration.max_retries
            else AGENT_DEFAULT_MAX_RETRIES
        )

        _auth_config = config.configuration.auth if config.configuration else None
        max_polling_time = (
            config.configuration.max_polling_time
            if config.configuration and config.configuration.max_polling_time
            else A2A_TASK_POLLING_MAX_WAIT
        )
        polling_initial_delay = (
            config.configuration.polling_initial_delay
            if config.configuration and config.configuration.polling_initial_delay
            else A2A_TASK_POLLING_INITIAL_DELAY
        )
        return cls(
            name=config.agent.name,
            description=config.agent.description,
            agent_card_path=agent_card_path,
            timeout=timeout,
            max_retries=max_retries,
            auth_config=_auth_config,
            max_polling_time=max_polling_time,
            polling_initial_delay=polling_initial_delay,
            push_notification_url=config.configuration.push_notification_url
            if config.configuration
            else None,
            pre_call_hook=config.configuration.pre_call_hook
            if config.configuration
            else None,
        )

    @property
    def protocol_type(self) -> ProtocolType:
        return ProtocolType.A2A

    # ============================================================================
    # Connection Management
    # ============================================================================

    async def connect(self) -> None:
        """Fetch the AgentCard and initialize the A2A client."""
        from rasa.nlu.utils import is_url

        try:
            auth_strategy = self._load_auth_strategy()
            if is_url(self._agent_card_path):
                self.agent_card = await A2AAgent._resolve_agent_card_with_retry(
                    self._agent_card_path,
                    self._timeout,
                    self._max_retries,
                    auth_strategy,
                )
            else:
                self.agent_card = A2AAgent._load_agent_card_from_file(
                    self._agent_card_path
                )
            structlogger.debug(
                "a2a_agent.from_config",
                event_info=f"Loaded agent card from {self._agent_card_path}",
                agent_card=message_to_dict(self.agent_card),
                json_formatting=["agent_card"],
            )

            self._client = await self._init_client()
            structlogger.debug(
                "a2a_agent.connect.agent_client_initialized",
                event_info=f"Initialized A2A client for agent '{self._name}'. "
                f"Performing health check using the URL "
                f"{_jsonrpc_interface_url(self.agent_card)}",
            )
        except Exception as exception:
            structlogger.error(
                "a2a_agent.connect.error",
                event_info="Failed to initialize A2A client",
                agent_name=self._name,
                error=str(exception),
            )
            raise AgentInitializationException(
                f"Failed to initialize A2A client "
                f"for agent '{self._name}': {exception}",
            ) from exception

        await self._perform_health_check()
        structlogger.debug(
            "a2a_agent.connect.success",
            event_info=f"Connected to A2A server '{self._name}' "
            f"at {_jsonrpc_interface_url(self.agent_card)}",
        )

    async def disconnect(self) -> None:
        """We don't need to explicitly disconnect the A2A client."""
        return

    # ============================================================================
    # Core Protocol Methods
    # ============================================================================

    async def process_input(self, agent_input: AgentInput) -> AgentInput:
        """Pre-process the input before sending it to the agent."""
        # A2A-specific input processing logic
        return agent_input

    @observe(
        name="a2a_agent.run",
        as_type="generation",
        capture_input=False,
        capture_output=False,
    )
    async def run(
        self,
        agent_input: AgentInput,
        output_channel: Optional[OutputChannel] = None,
        cancellation_token: Optional[CancellationToken] = None,
    ) -> AgentOutput:
        """Send a message to Agent/server and return response."""
        update_current_span_metadata(
            metadata={
                "prompt_type": "a2a_agent_run",
                "agent_name": self._name,
            }
        )
        generated_events: List[Event] = []
        sent_messages = _SentIntermediateRecords()
        output = await self._run_until_terminal(
            agent_input,
            output_channel,
            cancellation_token,
            generated_events=generated_events,
            sent_messages=sent_messages,
        )
        return output

    async def _run_until_terminal(
        self,
        agent_input: AgentInput,
        output_channel: Optional[OutputChannel],
        cancellation_token: Optional[CancellationToken],
        *,
        generated_events: List[Event],
        sent_messages: _SentIntermediateRecords,
    ) -> AgentOutput:
        """Stream the request, then poll if the stream ends before a terminal state."""
        send_result = await self._send_message_and_consume(
            agent_input=agent_input,
            generated_events=generated_events,
            output_channel=output_channel,
            operation="run",
            cancellation_token=cancellation_token,
            sent_messages=sent_messages,
        )

        if isinstance(send_result, AgentOutput):
            return send_result

        task_id = send_result.task_id
        events_received = send_result.events_received

        # The stream has ended, but we didn't get a terminal response.
        # Check if we received any events at all.
        if events_received == 0:
            structlogger.error(
                "a2a_agent.run.no_events_received",
                event_info="No events received from A2A agent after sending message",
                agent_name=self._name,
            )
            return AgentOutput(
                id=agent_input.id,
                status=AgentStatus.RECOVERABLE_ERROR,
                error_message="No events received from A2A agent",
                events=generated_events or None,
            )

        # Now we need to poll the task until it reaches a terminal state.
        if not task_id:
            structlogger.error(
                "a2a_agent.run.polling.missing_id",
                event_info="Missing task_id for polling",
                agent_name=self._name,
                task_id=task_id,
            )
            return AgentOutput(
                id=agent_input.id,
                status=AgentStatus.FATAL_ERROR,
                error_message="Missing task_id for polling",
                events=generated_events or None,
            )
        return await self._poll_task_until_terminal(
            agent_input=agent_input,
            task_id=task_id,
            generated_events=generated_events,
            max_wait=self._max_polling_time,
            initial_delay=self._polling_initial_delay,
            max_delay=MAX_AGENT_RETRY_DELAY_SECONDS,
            output_channel=output_channel,
            cancellation_token=cancellation_token,
            sent_messages=sent_messages,
        )

    @staticmethod
    def _create_cancelled_agent_output(
        agent_input: AgentInput,
        reason: str,
        generated_events: Optional[List[Event]] = None,
    ) -> AgentOutput:
        """Create an ``AgentOutput`` for a cancelled operation."""
        return AgentOutput(
            id=agent_input.id,
            status=AgentStatus.CANCELLED,
            metadata={
                AGENT_METADATA_CANCELLATION_REASON_KEY: reason,
            },
            events=generated_events or None,
        )

    async def _consume_stream(
        self,
        client_stream: AsyncIterator[StreamResponse],
        agent_input: AgentInput,
        generated_events: List[Event],
        output_channel: Optional[OutputChannel],
        sent_messages: _SentIntermediateRecords,
    ) -> StreamResult:
        """Consume A2A streaming events until a terminal state or stream end.

        Returns a ``StreamResult``.  When ``agent_output`` is not ``None`` the
        stream yielded a terminal response; otherwise the caller should fall
        through to polling using ``task_id`` / ``events_received``.

        Propagates ``A2AError`` / ``A2AClientError`` to the caller.
        """
        task_id: Optional[str] = None
        events_received = 0
        current_task: Optional[Task] = None
        async with aclosing(client_stream) as stream:  # type: ignore[type-var]
            async for event in stream:
                events_received += 1
                agent_output, current_task = await self._handle_send_message_response(
                    agent_input,
                    event,
                    generated_events,
                    current_task,
                    output_channel=output_channel,
                    sent_messages=sent_messages,
                )
                if current_task is not None and current_task.id:
                    task_id = current_task.id
                if agent_output is not None:
                    return StreamResult(agent_output, task_id, events_received)
        return StreamResult(None, task_id, events_received)

    async def _consume_stream_or_cancel(
        self,
        client_stream: AsyncIterator[StreamResponse],
        agent_input: AgentInput,
        generated_events: List[Event],
        output_channel: Optional[OutputChannel],
        cancellation_token: CancellationToken,
        sent_messages: _SentIntermediateRecords,
    ) -> StreamResult:
        """Race stream consumption against the cancellation token.

        If the token fires before the stream completes, the consume task is
        force-cancelled and a ``StreamResult`` with a ``CANCELLED``
        ``AgentOutput`` is returned immediately.

        If the stream completes first (with a terminal ``AgentOutput`` or by
        ending without one), the ``StreamResult`` is returned as-is — including
        any exception that ``_consume_stream`` would raise.
        """
        if cancellation_token.is_cancelled:
            # If already cancelled before we start, close the stream and return
            try:
                await client_stream.aclose()  # type: ignore[attr-defined]
            except Exception:
                structlogger.debug(
                    "a2a_agent.run.streaming.close_failed",
                    agent_name=self._name,
                    exc_info=True,
                )
            structlogger.info(
                "a2a_agent.run.streaming.cancelled",
                agent_name=self._name,
            )
            return StreamResult(
                self._create_cancelled_agent_output(
                    agent_input, A2A_CANCELLATION_REASON_STREAMING, generated_events
                ),
                task_id=None,
                events_received=0,
            )

        # Race two tasks: stream consumption vs. cancellation signal.
        # Whichever completes first wins; the loser is cancelled and we
        # suppress its CancelledError to ensure clean shutdown
        consume_task = asyncio.create_task(
            self._consume_stream(
                client_stream,
                agent_input,
                generated_events,
                output_channel,
                sent_messages,
            )
        )
        cancel_task = asyncio.create_task(cancellation_token.wait_until_cancelled())

        done, pending = await asyncio.wait(
            {consume_task, cancel_task},
            return_when=asyncio.FIRST_COMPLETED,
        )

        # Clean up the losing task
        for t in pending:
            t.cancel()
            try:
                await t
            except asyncio.CancelledError:
                pass

        # Stream finished first — return its result (or re-raise its exception)
        if consume_task in done:
            return consume_task.result()

        # Cancellation won — the stream was interrupted
        structlogger.info(
            "a2a_agent.run.streaming.cancelled",
            agent_name=self._name,
        )
        return StreamResult(
            self._create_cancelled_agent_output(
                agent_input, A2A_CANCELLATION_REASON_STREAMING, generated_events
            ),
            task_id=None,
            events_received=0,
        )

    async def _send_message_and_consume(
        self,
        agent_input: AgentInput,
        generated_events: List[Event],
        output_channel: Optional[OutputChannel],
        operation: str,
        cancellation_token: Optional[CancellationToken] = None,
        *,
        sent_messages: _SentIntermediateRecords,
    ) -> AgentOutput | StreamResult:
        if not self._client or not self.agent_card:
            structlogger.error(
                f"a2a_agent.{operation}.error",
                event_info="A2A client is not initialized. Call connect() first.",
            )
            return AgentOutput(
                id=agent_input.id,
                status=AgentStatus.FATAL_ERROR,
                error_message="Client not initialized",
                events=generated_events or None,
            )

        structlogger.info(
            f"a2a_agent.{operation}.start",
            event_info="Running A2A agent",
            agent_name=self._name,
        )
        try:
            message = await self._build_outbound_message(agent_input)
        except OutboundCallHookError as e:
            structlogger.error(
                f"a2a_agent.{operation}.pre_call_hook.error",
                event_info="Call metadata hook failed; not sending A2A message",
                agent_name=self._name,
                error=str(e),
            )
            return AgentOutput(
                id=agent_input.id,
                status=AgentStatus.FATAL_ERROR,
                error_message=f"Call metadata hook failed: {e!s}",
                events=generated_events or None,
            )

        try:
            stream = self._client.send_message(SendMessageRequest(message=message))
            if cancellation_token:
                result = await self._consume_stream_or_cancel(
                    stream,
                    agent_input,
                    generated_events,
                    output_channel,
                    cancellation_token,
                    sent_messages,
                )
            else:
                result = await self._consume_stream(
                    stream,
                    agent_input,
                    generated_events,
                    output_channel,
                    sent_messages,
                )
        except A2AClientError as exception:
            structlogger.error(
                f"a2a_agent.{operation}.send_message.error",
                event_info="Error during sending message to A2A agent",
                agent_name=self._name,
                error=str(exception),
            )
            return AgentOutput(
                id=agent_input.id,
                status=AgentStatus.FATAL_ERROR,
                error_message=f"Send message error: {exception!s}",
                events=generated_events or None,
            )
        except A2AError as exception:
            return self._handle_json_rpc_error_response(
                agent_input, exception, generated_events
            )

        if result.agent_output is not None:
            return result.agent_output

        return result

    async def run_async(
        self,
        agent_input: AgentInput,
        output_channel: Optional[OutputChannel] = None,
        cancellation_token: Optional[CancellationToken] = None,
    ) -> AgentOutput:
        """Send a message to Agent/server and return response."""
        generated_events: List[Event] = []
        sent_messages = _SentIntermediateRecords()
        send_result = await self._send_message_and_consume(
            agent_input=agent_input,
            generated_events=generated_events,
            output_channel=output_channel,
            operation="run_async",
            cancellation_token=cancellation_token,
            sent_messages=sent_messages,
        )

        if isinstance(send_result, AgentOutput):
            return send_result

        events_received = send_result.events_received

        # We didn't get a response.
        # Check if we received any events at all.
        # Agent might have accepted our request and is still processing.
        if events_received == 0:
            structlogger.error(
                "a2a_agent.run_async.no_events_received",
                event_info="No events received from A2A agent after sending message",
                agent_name=self._name,
            )
            return AgentOutput(
                id=agent_input.id,
                status=AgentStatus.RECOVERABLE_ERROR,
                error_message="No events received from A2A agent",
                events=generated_events or None,
            )

        return AgentOutput(
            id=agent_input.id,
            status=AgentStatus.FATAL_ERROR,
            error_message="Unrecoverable error from A2A agent",
            events=generated_events or None,
        )

    async def process_agent_output(self, output: AgentOutput) -> AgentOutput:
        """Post-process the output before returning it to Rasa.

        This method should be implemented to post-process the output before returning
        it to Rasa. This can be used to add any necessary metadata or context to the
        output, or to filter the output.

        ``unsent_response_message`` is chosen before this hook. Rewriting
        ``response_message`` rebuilds the unsent reply from the new text, with
        intermediate utterances that were already shown left out. Assign
        ``unsent_response_message`` in the hook, even to its current value,
        when that rebuilt reply is not what should be uttered.

        Args:
            output: The output from the agent as an AgentOutput object.

        Returns:
            The processed output from the agent as an AgentOutput object.
        """
        # A2A-specific output processing logic
        return output

    @staticmethod
    def _begin_unsent_hook_watch(output: AgentOutput) -> bool:
        """Clear the set-mark so a hook assignment of the same string shows up.

        Comparing the value cannot tell that assignment from the hook leaving
        the field alone, and ``""`` is interned so identity cannot either.
        """
        was_set = "unsent_response_message" in output.model_fields_set
        output.model_fields_set.discard("unsent_response_message")
        return was_set

    @staticmethod
    def _finish_unsent_hook_watch(
        source: AgentOutput, result: AgentOutput, was_set: bool
    ) -> bool:
        """Return whether the hook assigned ``unsent_response_message``.

        Restores the set-mark on ``source`` when the hook left the field
        alone, so a value chosen before the hook stays explicitly set.
        """
        assigned = "unsent_response_message" in result.model_fields_set
        if was_set and "unsent_response_message" not in source.model_fields_set:
            source.model_fields_set.add("unsent_response_message")
        return assigned

    @staticmethod
    def _align_unsent_after_output_hook(
        response_before: Optional[str],
        unsent_before: Optional[str],
        shown_texts: List[str],
        output: AgentOutput,
        hook_assigned_unsent: bool,
    ) -> None:
        """Rebuild the unsent reply when the hook rewrote ``response_message``.

        A streamed or polled run always sets ``unsent_response_message``, so
        the executor would otherwise utter that pre-hook snapshot. An
        assignment in the hook keeps that value, including the same string.
        """
        if unsent_before is None or hook_assigned_unsent:
            return
        if output.unsent_response_message != unsent_before:
            return
        if output.response_message == response_before:
            return
        output.unsent_response_message = _remove_sent_utterances(
            output.response_message or "", shown_texts
        )

    # ============================================================================
    # Message Processing & Response Handling
    # ============================================================================

    async def _handle_send_message_response(
        self,
        agent_input: AgentInput,
        response: StreamResponse,
        generated_events: List[Event],
        current_task: Optional[Task],
        output_channel: Optional[OutputChannel] = None,
        *,
        sent_messages: _SentIntermediateRecords,
    ) -> tuple[Optional[AgentOutput], Optional[Task]]:
        """Handle one ``StreamResponse`` from the A2A client.

        A stream yields ``task``, ``message``, ``status_update``, or
        ``artifact_update``. Status and artifact updates are folded into the
        task accumulated so far. A terminal task or a message returns an
        ``AgentOutput``; an in-progress ``task`` or ``status_update`` returns
        ``None`` so streaming or polling can continue. An ``artifact_update``
        only accumulates parts and does not send an intermediate message,
        because the chunk does not change ``status.message``.
        """
        if not isinstance(response, StreamResponse):
            return (
                self._handle_unexpected_response_type(
                    agent_input, response, generated_events
                ),
                current_task,
            )

        task, message = _apply_stream_chunk(response, current_task)
        if message is not None:
            return (
                self._handle_message_response(agent_input, message, generated_events),
                task,
            )
        if task is None:
            return (
                self._handle_unexpected_response_type(
                    agent_input, response, generated_events
                ),
                current_task,
            )

        if response.HasField("artifact_update"):
            # The chunk does not change status.message. Sending here would
            # repeat the last WORKING text once per artifact event.
            return None, task

        structlogger.debug(
            "a2a_agent.run.client_event_received",
            event_info="Received client event from A2A",
            task=message_to_dict(task),
            update_event=message_to_dict(response),
            json_formatting=["task", "update_event"],
        )
        return (
            await self._handle_task(
                agent_input=agent_input,
                task=task,
                generated_events=generated_events,
                sent_messages=sent_messages,
                output_channel=output_channel,
            ),
            task,
        )

    def _handle_json_rpc_error_response(
        self, agent_input: AgentInput, error: Any, generated_events: List[Event]
    ) -> AgentOutput:
        structlogger.error(
            "a2a_agent.run.error",
            event_info="Received JSON-RPC error response from A2A agent",
            agent_name=self._name,
            error=str(error),
        )
        if isinstance(
            error,
            (
                InternalError,
                InvalidAgentResponseError,
            ),
        ):
            return AgentOutput(
                id=agent_input.id,
                status=AgentStatus.RECOVERABLE_ERROR,
                error_message=str(error),
                events=generated_events or None,
            )
        else:
            return AgentOutput(
                id=agent_input.id,
                status=AgentStatus.FATAL_ERROR,
                error_message=str(error),
                events=generated_events or None,
            )

    def _handle_message_response(
        self, agent_input: AgentInput, message: Message, generated_events: List[Event]
    ) -> Optional[AgentOutput]:
        structlogger.debug(
            "a2a_agent.run.message_received",
            event_info="Received message from A2A",
            agent_name=self._name,
            message=message_to_dict(message),
            json_formatting=["message"],
        )
        metadata = self._create_a2a_specific_metadata(
            base_metadata=agent_input.metadata or {}, message=message
        )

        return AgentOutput(
            id=agent_input.id,
            status=AgentStatus.INPUT_REQUIRED,
            response_message=self._generate_response_message_from_parts(message.parts),
            metadata=metadata,
            events=generated_events or None,
        )

    def _handle_unexpected_response_type(
        self,
        agent_input: AgentInput,
        response_result: Any,
        generated_events: List[Event],
    ) -> AgentOutput:
        structlogger.error(
            "a2a_agent.run.unexpected_response_type",
            event_info="Received unexpected response type from A2A server "
            "during streaming",
            agent_name=self._name,
            response_type=type(response_result),
        )
        return AgentOutput(
            id=agent_input.id,
            status=AgentStatus.FATAL_ERROR,
            error_message=f"Unexpected response type: {type(response_result)}",
            events=generated_events or None,
        )

    async def _handle_task(
        self,
        agent_input: AgentInput,
        task: Task,
        generated_events: List[Event],
        sent_messages: Optional[_SentIntermediateRecords] = None,
        output_channel: Optional[OutputChannel] = None,
        *,
        dedupe_text_without_id: bool = False,
    ) -> Optional[AgentOutput]:
        """If task status is terminal (e.g. completed, failed) return AgentOutput.

        If the task is still in progress (i.e., submitted, working), return None,
        so that the streaming or polling agent can continue to wait for updates.
        """
        state = task.status.state
        state_name = _task_state_name(state)

        metadata = self._create_a2a_specific_metadata(
            base_metadata=agent_input.metadata or {}, task=task
        )
        if sent_messages is not None:
            sent_messages.record_streamed_artifacts(task)

        if state == TaskState.TASK_STATE_INPUT_REQUIRED:
            response_message = (
                self._generate_response_message_from_parts(task.status.message.parts)
                if task.status.HasField("message")
                else ""
            )  # This should not happen, but as type of message property
            # is optional, so we need to handle it

            structured_results = self.get_structured_results_from_task(
                agent_input, task
            )
            return AgentOutput(
                id=agent_input.id,
                status=AgentStatus.INPUT_REQUIRED,
                response_message=response_message,
                unsent_response_message=(
                    _remove_sent_utterances(response_message, sent_messages.shown_texts)
                    if sent_messages is not None
                    else None
                ),
                structured_results=structured_results,
                metadata=metadata,
                events=generated_events or None,
                task_id=task.id,
                context_id=task.context_id,
            )
        elif state == TaskState.TASK_STATE_COMPLETED:
            response_message, unsent_response_message = (
                self._generate_completed_response_messages(task, sent_messages)
            )
            structured_results = self.get_structured_results_from_task(
                agent_input, task
            )
            return AgentOutput(
                id=agent_input.id,
                status=AgentStatus.COMPLETED,
                response_message=response_message,
                unsent_response_message=unsent_response_message,
                structured_results=structured_results,
                metadata=metadata,
                events=generated_events or None,
                task_id=task.id,
                context_id=task.context_id,
            )
        elif state in {
            TaskState.TASK_STATE_FAILED,
            TaskState.TASK_STATE_CANCELED,
            TaskState.TASK_STATE_REJECTED,
            TaskState.TASK_STATE_AUTH_REQUIRED,
        }:
            structlogger.error(
                "a2a_agent.handle_task.unsuccessful_task_state",
                event_info="Task execution finished with an unsuccessful state",
                agent_name=self._name,
                state=state_name,
            )
            return AgentOutput(
                id=agent_input.id,
                status=AgentStatus.RECOVERABLE_ERROR,
                error_message=f"Task state: {state_name}",
                metadata=metadata,
                events=generated_events or None,
                task_id=task.id,
                context_id=task.context_id,
            )
        elif state in {TaskState.TASK_STATE_SUBMITTED, TaskState.TASK_STATE_WORKING}:
            # The task is still in progress, send intermediate status update
            # to the user and return None to continue waiting for updates
            if not self.is_async():
                await self._send_intermediate_message(
                    agent_input,
                    task,
                    generated_events,
                    sent_messages,
                    output_channel,
                    dedupe_text_without_id=dedupe_text_without_id,
                )
                return None

            if not task.id:
                structlogger.error(
                    "a2a_agent.handle_task.missing_task_id",
                    event_info="Async task status received without task id",
                    agent_name=self._name,
                    state=state_name,
                )
                return AgentOutput(
                    id=agent_input.id,
                    status=AgentStatus.FATAL_ERROR,
                    error_message="Async task status received without task id",
                    metadata=metadata,
                    events=generated_events or None,
                    task_id=None,
                    context_id=task.context_id,
                )

            response_message = (
                self._generate_response_message_from_parts(task.status.message.parts)
                if task.status.HasField("message")
                else "Task is submitted successfully"
            )
            structured_results = (
                self._generate_structured_results_from_artifacts(
                    agent_input, task.artifacts
                )
                if task.artifacts
                else None
            )
            return AgentOutput(
                id=agent_input.id,
                status=AgentStatus.SUBMITTED,
                response_message=response_message,
                structured_results=structured_results,
                metadata=metadata,
                events=generated_events or None,
                task_id=task.id,
                context_id=task.context_id,
            )
        else:
            # Unmapped states, including TASK_STATE_UNSPECIFIED, are fatal.
            # SDK 1.0 removed TaskState.unknown, which used to keep waiting.
            structlogger.error(
                "a2a_agent.handle_task.unexpected_task_state",
                event_info="Unexpected task state received from A2A",
                agent_name=self._name,
                state=state_name,
            )
            return AgentOutput(
                id=agent_input.id,
                status=AgentStatus.FATAL_ERROR,
                error_message=f"Unexpected task state: {state_name}",
                metadata=metadata,
                events=generated_events or None,
                task_id=task.id,
                context_id=task.context_id,
            )

    def _get_artifacts_for_structured_results(self, task: Task) -> List[Artifact]:
        """Build list of artifacts to use for structured_results from task.

        Includes task.artifacts and, if task.status.message has DataParts or
        FileWithUri (e.g. callback_slots), a synthetic artifact for those parts
        so they reach the client.
        """
        artifacts: List[Artifact] = list(task.artifacts or [])
        if (
            task.status.HasField("message")
            and task.status.message.parts
            and A2AAgent._parts_contain_structured_data(task.status.message.parts)
        ):
            artifacts.append(
                Artifact(artifact_id="status_message", parts=task.status.message.parts)
            )
        return artifacts

    def get_structured_results_from_task(
        self, agent_input: AgentInput, task: Task
    ) -> Optional[List[List[Dict[str, Any]]]]:
        """Build structured_results from task artifacts and status message parts.

        Covers both input_required and completed states so DataParts (e.g.
        callback_slots) in the status message reach the client.
        """
        artifacts = self._get_artifacts_for_structured_results(task)
        if not artifacts:
            return None
        return self._generate_structured_results_from_artifacts(agent_input, artifacts)

    @staticmethod
    def _parts_contain_structured_data(parts: List[Part]) -> bool:
        """Return True if parts contain data or a file URL."""
        for part in parts or []:
            data = part_data(part)
            if data:
                return True
            if part.HasField("url") and part.url:
                return True
        return False

    def _append_shown_intermediate(
        self,
        task: Task,
        message: str,
        agent_input: AgentInput,
        generated_events: List[Event],
        sent_messages: Optional[_SentIntermediateRecords],
    ) -> None:
        """Store an intermediate utterance that the channel write returned."""
        generated_events.append(
            BotUttered(
                text=message,
                metadata=self._create_intermediate_message_bot_uttered_event_metadata(
                    task, agent_input.metadata or {}
                ),
            )
        )
        if sent_messages is None:
            return
        artifact_id = (
            _streamed_artifact_id(task.status.message)
            if task.status.HasField("message")
            else ""
        )
        sent_messages.record_shown(message, artifact_id=artifact_id)

    async def _await_intermediate_channel_send(
        self,
        output_channel: OutputChannel,
        recipient_id: str,
        message: str,
    ) -> _IntermediateSendOutcome:
        """Wait for one channel write. Do not store the utterance.

        Turn cancellation cancels an in-flight write and does not wait for
        it: the channel may already have delivered the text, and waiting
        would let a stuck socket pin the cancelled turn. If the write has
        already returned, this returns ``SENT`` and leaves the cancellation
        pending so the caller can store the utterance and then re-raise.
        A playback timeout leaves the write running so TTS is not cut off.
        """
        timeout_seconds, cancel_on_timeout = _intermediate_send_timeout(output_channel)
        send_task = asyncio.create_task(
            output_channel.send_text_message(recipient_id=recipient_id, text=message)
        )
        send_task.add_done_callback(_consume_send_result)
        timed_out = False
        try:
            _done, pending = await asyncio.wait({send_task}, timeout=timeout_seconds)
            timed_out = bool(pending)
        except asyncio.CancelledError:
            if not _channel_send_succeeded(send_task):
                raise
            return _IntermediateSendOutcome.SENT
        finally:
            if not send_task.done() and (not timed_out or cancel_on_timeout):
                send_task.cancel()
        if not send_task.done() or send_task.cancelled():
            structlogger.warning(
                "a2a_agent.send_intermediate_message.timeout",
                event_info=(
                    "Intermediate message send timed out; the stream "
                    "continues without storing it."
                ),
                agent_name=self._name,
                recipient_id=recipient_id,
                timeout_seconds=timeout_seconds,
                cancel_on_timeout=cancel_on_timeout,
            )
            return _IntermediateSendOutcome.TIMED_OUT
        send_error = send_task.exception()
        if send_error is not None:
            raise send_error
        return _IntermediateSendOutcome.SENT

    async def _send_intermediate_message(
        self,
        agent_input: AgentInput,
        task: Task,
        generated_events: List[Event],
        sent_messages: Optional[_SentIntermediateRecords] = None,
        output_channel: Optional[OutputChannel] = None,
        *,
        dedupe_text_without_id: bool = False,
    ) -> None:
        """Send an intermediate message to the user if the task is in progress.

        The channel send is awaited before the caller handles the next stream
        or poll event. Channels that return from the write without waiting for
        playback are bounded by a short timeout and cancelled when it expires.
        Voice waits for earlier audio and then streams TTS, so that send gets
        a longer bound and is left running if the bound expires. The
        ``BotUttered`` is stored here, and only when the send finishes in
        time. An in-flight write is cancelled with the turn and not stored,
        even if the channel already delivered the text. A write that has
        already returned is stored before that cancellation propagates.

        Args:
            agent_input: The agent input containing user information.
            task: The task from the A2A stream.
            generated_events: Events generated so far for this run.
            sent_messages: Statuses already scheduled in this run. ``None``
                disables dedupe.
            output_channel: The output channel for sending messages.
            dedupe_text_without_id: When true, skip an id-less status whose
                text was already scheduled. Polling sets this. Streaming leaves
                it false so two id-less messages with the same text both appear.
        """
        if output_channel is None:
            structlogger.debug(
                "a2a_agent.send_intermediate_message.no_output_channel",
                event_info=(
                    "No output channel provided, cannot send intermediate message.",
                ),
                agent_name=self._name,
            )
            return

        recipient_id = agent_input.recipient_id
        if not recipient_id:
            structlogger.debug(
                "a2a_agent.send_intermediate_message.no_recipient_id",
                event_info=(
                    "No recipient ID provided in agent input, cannot send "
                    "intermediate message."
                ),
                agent_name=self._name,
            )
            return

        try:
            message = (
                self._generate_response_message_from_parts(task.status.message.parts)
                if task.status.HasField("message")
                else ""
            )
            structlogger.debug(
                "a2a_agent.send_intermediate_message.debug", task=message_to_dict(task)
            )
            if len(message) == 0:
                structlogger.debug(
                    "a2a_agent.send_intermediate_message.empty_message",
                    event_info="Skipping sending empty intermediate message",
                    agent_name=self._name,
                    recipient_id=recipient_id,
                )
                return

            message_id = (
                task.status.message.message_id
                if task.status.HasField("message")
                else ""
            )
            if sent_messages is not None and sent_messages.should_skip(
                message_id,
                message,
                dedupe_text=dedupe_text_without_id,
            ):
                structlogger.debug(
                    "a2a_agent.send_intermediate_message.duplicate_skipped",
                    event_info=(
                        "Skipping intermediate message already scheduled in this run"
                    ),
                    agent_name=self._name,
                    recipient_id=recipient_id,
                )
                return

            structlogger.debug(
                "a2a_agent.send_intermediate_message.sending",
                event_info="Sending intermediate message to output channel",
                agent_name=self._name,
                recipient_id=recipient_id,
                message=message,
            )

            if sent_messages is not None:
                sent_messages.record(message_id, message)
            outcome = await self._await_intermediate_channel_send(
                output_channel, recipient_id, message
            )
        except asyncio.CancelledError:
            raise
        except Exception as e:
            structlogger.error(
                "a2a_agent.send_intermediate_message.error",
                event_info="Error sending intermediate message to output channel",
                agent_name=self._name,
                recipient_id=recipient_id,
                error=str(e),
            )
            return

        if outcome is not _IntermediateSendOutcome.SENT:
            return
        self._append_shown_intermediate(
            task, message, agent_input, generated_events, sent_messages
        )
        # SENT during cancellation means the write had already returned.
        # Store it above, then propagate so the turn still ends.
        running = asyncio.current_task()
        if running is not None and running.cancelling():
            raise asyncio.CancelledError()

    def _create_intermediate_message_bot_uttered_event_metadata(
        self, task: Task, base_metadata: Optional[Dict[str, Any]] = None
    ) -> Dict[str, str]:
        # Intermediate messages are emitted directly by the agent to the output
        # channel (not via predicted Actions from the policy), so we must include
        # both the generic source info and the A2A-specific IDs here
        raw = self._create_a2a_specific_metadata(base_metadata or {}, task=task)
        mapped = map_agent_metadata_to_bot_uttered(raw)
        mapped.setdefault(UTTER_SOURCE_METADATA_KEY, self.__class__.__name__)
        mapped.setdefault(BOT_UTTERANCE_AGENT_NAME_KEY, self._name)
        mapped.setdefault(
            BOT_UTTERANCE_AGENT_MESSAGE_TYPE_KEY,
            BOT_UTTERANCE_AGENT_MESSAGE_TYPE_INTERMEDIATE_MESSAGE,
        )
        return mapped

    @staticmethod
    def _create_a2a_specific_metadata(
        base_metadata: Optional[Dict[str, Any]] = None,
        message: Optional[Message] = None,
        task: Optional[Task] = None,
    ) -> Dict[str, Any]:
        # Build only A2A-specific metadata to be forwarded upstream.
        # We avoid setting UTTER_SOURCE_METADATA_KEY or message type here,
        # as those are centrally handled by AgentManager and the agent executor.

        # Start from a shallow copy to avoid mutating the input metadata
        metadata: Dict[str, Any] = dict(base_metadata) if base_metadata else {}

        # Avoid carrying over stale message IDs or timestamps from previous outputs.
        # Only add them when the current message/task provides fresh values.
        metadata.pop(BOT_UTTERANCE_MESSAGE_ID_KEY, None)
        metadata.pop(BOT_UTTERANCE_AGENT_MESSAGE_TIMESTAMP_KEY, None)

        if message is not None:
            # IDs from a direct message response
            if message.message_id:
                metadata[BOT_UTTERANCE_MESSAGE_ID_KEY] = message.message_id
            if message.task_id:
                metadata[A2A_AGENT_TASK_ID_KEY] = message.task_id
            if message.context_id:
                metadata[A2A_AGENT_CONTEXT_ID_KEY] = message.context_id

        if task is not None:
            # IDs from a task-based response
            metadata[A2A_AGENT_TASK_ID_KEY] = task.id
            # Prefer message-provided context id if available,
            # otherwise fall back to task
            metadata[A2A_AGENT_CONTEXT_ID_KEY] = task.context_id
            if task.status.HasField("message"):
                status_message = task.status.message
                if status_message.message_id:
                    metadata[BOT_UTTERANCE_MESSAGE_ID_KEY] = status_message.message_id
                if status_message.context_id:
                    metadata[A2A_AGENT_CONTEXT_ID_KEY] = status_message.context_id
            if task.status.HasField("timestamp"):
                metadata[BOT_UTTERANCE_AGENT_MESSAGE_TIMESTAMP_KEY] = (
                    task.status.timestamp.ToJsonString()
                )
        return metadata

    # ============================================================================
    # Message Preparation & Formatting
    # ============================================================================

    @staticmethod
    def build_a2a_outbound_call_context(
        agent_input: AgentInput,
    ) -> A2AOutboundCallContext:
        """Build an ``A2AOutboundCallContext`` for an outbound A2A call."""
        metadata = agent_input.metadata or {}
        sender_id = (
            agent_input.recipient_id or metadata.get(AGENT_METADATA_SENDER_ID_KEY) or ""
        )
        return A2AOutboundCallContext(
            sender_id=sender_id,
            agent_id=agent_input.id,
            context_id=metadata.get(A2A_AGENT_CONTEXT_ID_KEY),
            task_id=metadata.get(A2A_AGENT_TASK_ID_KEY),
            turn_metadata=deepcopy(metadata),
        )

    async def _build_outbound_message(self, agent_input: AgentInput) -> Message:
        """Resolve call-time credentials and build the outbound A2A message.

        Invokes ``configuration.pre_call_hook`` when configured. The returned
        metadata is merged into ``Message.metadata`` only; ``agent_input`` is
        never updated with hook output so sensitive values are not retained
        beyond the outbound call.

        Raises:
            OutboundCallHookError: If the hook fails. The caller must not send
                the message in that case (fail-fast).
        """
        hook_result: Optional[OutboundCallResult] = None
        if self._pre_call_hook:
            context = self.build_a2a_outbound_call_context(agent_input)
            hook = load_call_hook(self._pre_call_hook)
            hook_result = await invoke_a2a_call_hook(hook, context)
        return self._prepare_message(agent_input, hook_result=hook_result)

    @staticmethod
    def _prepare_message(
        agent_input: AgentInput,
        hook_result: Optional[OutboundCallResult] = None,
    ) -> Message:
        parts: List[Part] = []
        if (
            agent_input.metadata
            and A2A_AGENT_CONTEXT_ID_KEY in agent_input.metadata
            and not agent_input.metadata.get(AGENT_METADATA_RESUMED_AFTER_INTERRUPTION)
        ):
            # Agent knows the conversation history already, send the last
            # user message only
            parts.append(text_part(agent_input.user_message))
        else:
            # Send the full conversation history. Also used when the agent is
            # being resumed after interruption: the remote backend's session
            # context may have expired, so full history is needed to rebuild it.
            parts.append(text_part(agent_input.conversation_history))

        if len(agent_input.slots) > 0:
            slots_dict: Dict[str, Any] = {
                "slots": {
                    slot.name: slot.value
                    for slot in agent_input.slots
                    if slot.value is not None
                }
            }
            parts.append(data_part(slots_dict))

        # Pass through metadata (e.g. auth tokens, user context) to the backend
        # without processing by the LLM. Hook output is merged here only — never
        # written back onto ``agent_input``.
        message_metadata = merge_call_metadata(agent_input.metadata, hook_result)
        input_metadata = agent_input.metadata or {}
        agent_message = Message(
            role=Role.ROLE_USER,
            parts=parts,
            message_id=str(uuid.uuid4()),
            context_id=input_metadata.get(A2A_AGENT_CONTEXT_ID_KEY) or "",
            task_id=input_metadata.get(A2A_AGENT_TASK_ID_KEY) or "",
        )
        if message_metadata:
            ParseDict(message_metadata, agent_message.metadata)
        structlogger.debug(
            "a2a_agent.prepare_message",
            event_info="Prepared message to send to A2A server",
            agent_name=agent_input.id,
            message=message_to_dict(agent_message),
            json_formatting=["message"],
        )
        return agent_message

    # ============================================================================
    # Task Management & Polling
    # ============================================================================

    async def _poll_task_until_terminal(
        self,
        agent_input: AgentInput,
        task_id: str,
        generated_events: List[Event],
        max_wait: int,
        initial_delay: float,
        max_delay: int,
        output_channel: Optional[OutputChannel] = None,
        cancellation_token: Optional[CancellationToken] = None,
        *,
        sent_messages: _SentIntermediateRecords,
    ) -> AgentOutput:
        """Poll the task status until it reaches a terminal state or times out."""
        if not self._client:
            structlogger.error(
                "a2a_agent.poll_task_until_terminal.error",
                event_info="A2A client is not initialized. Call connect() first.",
            )
            return AgentOutput(
                id=agent_input.id,
                status=AgentStatus.FATAL_ERROR,
                error_message="Client not initialized",
            )

        structlogger.debug(
            "a2a_agent.poll_task_until_terminal.start",
            event_info="Start polling task from A2A server",
            agent_name=self._name,
            task_id=task_id,
            max_wait=max_wait,
            initial_delay=initial_delay,
            max_delay=max_delay,
        )
        start_time = time.monotonic()
        delay = initial_delay

        while True:
            if cancellation_token and cancellation_token.is_cancelled:
                structlogger.info(
                    "a2a_agent.poll_task_until_terminal.cancelled",
                    agent_name=self._name,
                    task_id=task_id,
                )
                return self._create_cancelled_agent_output(
                    agent_input, A2A_CANCELLATION_REASON_POLLING, generated_events
                )

            try:
                task = await self._client.get_task(GetTaskRequest(id=task_id))
                agent_output = await self._handle_task(
                    agent_input=agent_input,
                    task=task,
                    generated_events=generated_events,
                    sent_messages=sent_messages,
                    output_channel=output_channel,
                    dedupe_text_without_id=True,
                )
                if agent_output is not None:
                    # Reached a terminal state, return the output
                    return agent_output

                elapsed = time.monotonic() - start_time
                if elapsed >= max_wait:
                    structlogger.debug(
                        "a2a_agent.poll_task_until_terminal.timeout",
                        event_info="Polling task from A2A server timed out",
                        agent_name=self._name,
                        task_id=task_id,
                        elapsed=elapsed,
                        max_wait=max_wait,
                    )
                    return AgentOutput(
                        id=agent_input.id,
                        status=AgentStatus.FATAL_ERROR,
                        error_message="Polling timed out",
                        events=generated_events or None,
                    )

                structlogger.info(
                    "a2a_agent.poll_task_until_terminal.waiting",
                    event_info="Task not in terminal state yet, waiting to poll again",
                    delay=delay,
                    agent_name=self._name,
                    task_id=task_id,
                    elapsed=elapsed,
                    max_wait=max_wait,
                )

                if cancellation_token:
                    cancelled = await cancellation_token.wait(timeout=delay)
                    if cancelled:
                        structlogger.info(
                            "a2a_agent.poll_task_until_terminal.cancelled",
                            agent_name=self._name,
                            task_id=task_id,
                        )
                        return self._create_cancelled_agent_output(
                            agent_input,
                            A2A_CANCELLATION_REASON_POLLING,
                            generated_events,
                        )
                else:
                    await asyncio.sleep(delay)

                # Exponential backoff with cap
                delay = min(delay * 2, max_delay)

            except A2AError as exception:
                structlogger.error(
                    "a2a_agent.poll_task_until_terminal.error",
                    event_info="Error during polling task from A2A server",
                    agent_name=self._name,
                    error=str(exception),
                )
                return AgentOutput(
                    id=agent_input.id,
                    status=AgentStatus.FATAL_ERROR,
                    error_message=f"Polling error: {exception!s}",
                    events=generated_events or None,
                )

    # ============================================================================
    # Response Generation & Formatting
    # ============================================================================

    @staticmethod
    def _generate_response_message_from_parts(parts: Optional[List[Part]]) -> str:
        """Convert a list of Part objects to a single string message."""
        result = ""
        if not parts:
            return result
        for part in parts:
            if part.HasField("text") and part.text:
                result += part.text + "\n"
            elif part_data(part) is not None:
                # Data parts are returned as structured results, not text.
                continue
            elif part.HasField("url") and part.url:
                result += f"File: {part.url}\n"
            else:
                structlogger.warning(
                    "a2a_agent._parts_to_single_message.warning",
                    event_info="Unsupported part type encountered",
                    part_type=part.WhichOneof("content"),
                )
        return result.strip()

    @staticmethod
    def _generate_completed_response_messages(
        task: Task,
        sent_messages: Optional[_SentIntermediateRecords] = None,
    ) -> tuple[str, Optional[str]]:
        """Return the full completed reply and the part not yet shown.

        The final text may be in the task status, the artifacts, or both.
        The second value is ``None`` when there is no send record. Otherwise
        it is the full reply with shown status segments removed.

        Artifacts are chosen against the full status text, so removing shown
        segments does not bring back an artifact that repeats that text.
        Link data comes from ``sent_messages`` when the caller has already
        recorded this task. With no record, links are read from the task.

        Args:
            task: The completed task.
            sent_messages: What this run has already shown. ``None`` uses only
                the links still present on the task.
        """
        status_message = (
            A2AAgent._generate_response_message_from_parts(task.status.message.parts)
            if task.status.HasField("message")
            else ""
        )
        if sent_messages is not None:
            link_texts: Mapping[str, str] = sent_messages.artifact_link_texts
            streamed_artifact_ids: AbstractSet[str] = (
                sent_messages.streamed_artifact_ids
            )
            shown_artifact_ids: AbstractSet[str] = sent_messages.shown_artifact_ids
        else:
            link_texts = _artifact_link_texts(task)
            streamed_artifact_ids = _streamed_artifact_ids(task)
            shown_artifact_ids = frozenset()
        seen: List[str] = [status_message] if status_message else []
        artifact_messages: List[str] = []
        for artifact in task.artifacts:
            parts = list(artifact.parts)
            if (
                artifact.artifact_id in streamed_artifact_ids
                and _skip_linked_artifact_text(
                    artifact.artifact_id,
                    status_message=status_message,
                    shown_artifact_ids=shown_artifact_ids,
                    link_texts=link_texts,
                )
            ):
                parts = [part for part in parts if not part.HasField("text")]
            message = A2AAgent._generate_response_message_from_parts(parts)
            if message and message not in seen:
                seen.append(message)
                artifact_messages.append(message)

        def joined(status: str) -> str:
            parts = [status] if status else []
            return "\n".join(parts + artifact_messages)

        full_reply = joined(status_message)
        if sent_messages is None:
            return full_reply, None
        unsent_status = _remove_sent_utterances(
            status_message, sent_messages.shown_texts
        )
        return full_reply, joined(unsent_status)

    @staticmethod
    def _generate_structured_results_from_artifacts(
        agent_input: AgentInput, artifacts: List[Artifact]
    ) -> Optional[List[List[Dict[str, Any]]]]:
        structured_results_of_current_iteration: List[Dict[str, Any]] = []
        # There might be multiple artifacts in the response, each of them might
        # contain multiple parts. We will treat each DataPart in each artifact
        # as a separate tool result. The tool name will be the agent ID + index
        # of the artifact + index of the part.
        # E.g., foo_0_1, foo_0_2, foo_1_0, etc.
        for artifact_index, artifact in enumerate(artifacts):
            for part_index, part in enumerate(artifact.parts):
                data = part_data(part)
                if data:
                    structured_result = {
                        "name": f"{agent_input.id}_{artifact_index}_{part_index}",
                        "type": "data",
                        "result": data,
                    }
                    structured_results_of_current_iteration.append(structured_result)
                elif part.HasField("url") and part.url:
                    structured_result = {
                        "name": f"{agent_input.id}_{artifact_index}_{part_index}",
                        "type": "file",
                        "result": {
                            "uri": part.url,
                            "name": part.filename or None,
                            "mime_type": part.media_type or None,
                        },
                    }
                    structured_results_of_current_iteration.append(structured_result)

        previous_structured_results: List[List[Dict[str, Any]]] = (
            agent_input.metadata.get(AGENT_METADATA_STRUCTURED_RESULTS_KEY, []) or []
        )
        previous_structured_results.append(structured_results_of_current_iteration)

        return previous_structured_results

    # ============================================================================
    # Agent Card Management
    # ============================================================================

    @staticmethod
    def _load_agent_card_from_file(agent_card_path: str) -> AgentCard:
        """Load agent card from JSON file."""
        try:
            with open(os.path.abspath(agent_card_path), "r") as f:
                card_data = json.load(f)
            return parse_agent_card(card_data)

        except FileNotFoundError as e:
            raise AgentInitializationException(
                f"Agent card file not found: {agent_card_path}",
            ) from e
        except (IOError, PermissionError) as e:
            raise AgentInitializationException(
                f"Error reading agent card file {agent_card_path}: {e}",
            ) from e
        except json.JSONDecodeError as e:
            raise AgentInitializationException(
                f"Invalid JSON in agent card file {agent_card_path}: {e}",
            ) from e
        except (ParseError, ValueError) as e:
            raise AgentInitializationException(
                f"Failed to load agent card from {agent_card_path}: {e}",
            ) from e

    @staticmethod
    async def _resolve_agent_card_with_retry(
        agent_card_path: str,
        timeout: int,
        max_retries: int,
        auth_strategy: Optional[AgentAuthStrategy] = None,
    ) -> AgentCard:
        """Resolve the agent card from a given path or URL."""
        # split agent_card_path into base URL and path
        try:
            url_parts = urlparse(agent_card_path)
            base_url = f"{url_parts.scheme}://{url_parts.netloc}"
            path = url_parts.path
        except ValueError:
            raise RasaException(f"Could not parse the URL: '{agent_card_path}'.")
        structlogger.debug(
            "a2a_agent.resolve_agent_card",
            event_info="Resolving agent card from remote URL",
            agent_card_path=agent_card_path,
            base_url=base_url,
            path=path,
            timeout=timeout,
        )

        for attempt in range(max_retries):
            if attempt > 0:
                structlogger.debug(
                    "a2a_agent.resolve_agent_card.retrying",
                    agent_card_path=f"{base_url}/{path}",
                    attempt=attempt + 1,
                    num_retries=max_retries,
                )

            try:
                agent_card = await A2ACardResolver(
                    httpx.AsyncClient(timeout=timeout, auth=auth_strategy),
                    base_url=base_url,
                    agent_card_path=path,
                ).get_agent_card()

                if agent_card:
                    return agent_card
            except A2AClientError as exception:
                structlogger.warning(
                    "a2a_agent.resolve_agent_card.error",
                    event_info="Error while resolving agent card",
                    agent_card_path=agent_card_path,
                    attempt=attempt + 1,
                    num_retries=max_retries,
                    error=str(exception),
                )
                if attempt < max_retries - 1:
                    # exponential backoff - wait longer with each retry
                    # 1 second, 2 seconds, 4 seconds, etc.
                    await asyncio.sleep(min(2**attempt, MAX_AGENT_RETRY_DELAY_SECONDS))

        raise AgentInitializationException(
            f"Failed to resolve agent card from {agent_card_path} after "
            f"{max_retries} attempts.",
        )

    # ============================================================================
    # Client Initialization & Health Checks
    # ============================================================================

    def _load_auth_strategy(self) -> Optional[AgentAuthStrategy]:
        agent_auth_manager = AgentAuthManager.load_auth(self._auth_config)
        return agent_auth_manager.get_auth() if agent_auth_manager else None

    def _supports_push_notifications(self) -> bool:
        return bool(
            self.agent_card is not None
            and self.agent_card.capabilities.push_notifications
        )

    async def _init_client(self, for_health_check: bool = False) -> Client:
        auth_strategy = self._load_auth_strategy()
        use_push_notifications = (
            self._push_notification_url is not None
            and self._supports_push_notifications()
        )

        push_notification_config = (
            TaskPushNotificationConfig(
                url=f"{self._push_notification_url}/agent/task_update",
            )
            if use_push_notifications and not for_health_check
            else None
        )

        if self.agent_card is None:
            raise AgentInitializationException("Agent card is not loaded")

        return await create_client(
            self.agent_card,
            client_config=ClientConfig(
                httpx_client=httpx.AsyncClient(
                    timeout=self._timeout, auth=auth_strategy
                ),
                polling=bool(use_push_notifications or for_health_check),
                streaming=not use_push_notifications,
                supported_protocol_bindings=[
                    TransportProtocol.JSONRPC,
                    TransportProtocol.HTTP_JSON,
                    TransportProtocol.GRPC,
                ],
                accepted_output_modes=self.__SUPPORTED_OUTPUT_MODES,
                push_notification_config=push_notification_config,
            ),
        )

    async def _perform_health_check(self) -> None:
        client = await self._init_client(for_health_check=True)
        card_url = _jsonrpc_interface_url(self.agent_card) if self.agent_card else ""

        if not client or not self.agent_card:
            structlogger.error(
                "a2a_agent.health_check.error",
                event_info="A2A client is not initialized. Call connect() first.",
            )
            raise AgentInitializationException("Client not initialized")

        try:
            test_message = Message(
                role=Role.ROLE_USER,
                parts=[text_part("hello")],
                message_id=str(uuid.uuid4()),
            )
            # Use aclosing to ensure proper cleanup of the async generator
            stream = client.send_message(SendMessageRequest(message=test_message))
            async with aclosing(stream) as stream:  # type: ignore[type-var]
                async for event in stream:
                    if isinstance(event, StreamResponse) and (
                        event.HasField("task")
                        or event.HasField("message")
                        or event.HasField("status_update")
                        or event.HasField("artifact_update")
                    ):
                        # We got a valid response, health check succeeded
                        return

                    event_info = "Unexpected response type during health check"
                    structlogger.error(
                        "a2a_agent.health_check.unexpected_response",
                        event_info=event_info,
                        agent_name=self._name,
                        response=event,
                        url=card_url,
                    )
                    raise AgentInitializationException(f"{event_info}: {event}")
                # If the loop completes with no return, no events were received
                event_info = (
                    f"Health check failed for A2A agent '{self._name}' "
                    f"at {card_url}: no events received"
                )
                structlogger.error(
                    "a2a_agent.health_check.no_events",
                    event_info=event_info,
                    agent_name=self._name,
                    url=card_url,
                )
                raise AgentInitializationException(event_info)
        except Exception as exception:
            event_info = (
                f"Health check failed for A2A agent '{self._name}' at "
                f"{card_url}: {exception!s}"
            )
            structlogger.error(
                "a2a_agent.health_check.failed",
                event_info=event_info,
                agent_name=self._name,
                error=str(exception),
                url=card_url,
            )
            raise AgentInitializationException(event_info) from exception

    def is_async(self) -> bool:
        """Determines if the agent supports sending results via async updates.

        For A2A agent, async updates are supported if agent supports push notifications
        and if Rasa supplies the URL via which push notifications are to be sent.
        """
        use_push_notifications = (
            self._push_notification_url is not None
            and self._supports_push_notifications()
        )

        structlogger.debug(
            "a2a_agent.is_async",
            use_push_notifications=use_push_notifications,
            agent_name=self._name,
        )

        return use_push_notifications
